class Solution {
public:
    ListNode* rotateRight(ListNode* head, int k) {
        if (!head || !head->next || k == 0) return head;
        int n = 1;
        ListNode* tail = head;
        while (tail->next) { tail = tail->next; n++; }
        k %= n;
        if (k == 0) return head;
        for (int i = 0; i < k; ++i) {
            ListNode* prev = nullptr;
            ListNode* cur = head;
            while (cur->next) { prev = cur; cur = cur->next; }
            prev->next = nullptr;
            cur->next = head;
            head = cur;
        }
        return head;
    }
};

