        if (head == null || head.next == null || k == 0) return head;
        int n = 1;
        ListNode tail = head;
        while (tail.next != null) { tail = tail.next; n++; }
        k %= n;
        if (k == 0) return head;
        for (int i = 0; i < k; i++) {
            ListNode prev = null;
            ListNode cur = head;
            while (cur.next != null) { prev = cur; cur = cur.next; }
            prev.next = null;
            cur.next = head;
            head = cur;
        }
        return head;
    }
}

